  /**
   * Returns the display/print friendly parameter information
   *
   * Notes:
   *  - Private
   *
   * Related Tickets:
   *  -
   *
   * @author Martin D'Souza
   * @created 20-Jan-2013
   * @param p_parms Array of parameters (can be null)
   * @return Clob of param information
   */
CREATE OR REPLACE FUNCTION logger_get_param_clob (p_params logger.tab_param) RETURNS text AS $body$
DECLARE

    l_return text;
    l_no_vars constant varchar(255) := 'No params defined';
    l_index integer;

BEGIN

    $if $$no_op $then
      return null;
    $else
      -- Generate line feed delimited list
      if p_params.count > 0 then
        -- Using while true ... option allows for unordered param list
        l_index := p_params.first;
        while true loop
          l_return := l_return || p_params[l_index].name || ': ' || p_params[l_index].val;

          l_index := p_params.next(l_index);

          if coalesce(l_index::text, '') = '' then
            exit;
          else
            l_return := l_return || current_setting('logger.gc_line_feed')::varchar(1);
          end if;
        end loop;

      else
        -- No Parameters
        l_return := l_no_vars;
      end if;

      return l_return;
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
