CREATE OR REPLACE PROCEDURE logger_append_ctx (p_name text) AS $body$
DECLARE

      r_pad bigint := 30;
      l_value varchar(100);

      invalid_userenv_parm exception;


    
BEGIN
      l_value := sys_context('USERENV',p_name);

      if p_show_null or (l_value IS NOT NULL AND l_value::text <> '') then
        if p_vertical then
          l_ctx := l_ctx || rpad(p_name,r_pad,' ')||': '|| l_value || current_setting('logger.gc_cflf')::varchar(2);
        else
          l_ctx := l_ctx || p_name||': '|| l_value ||', ';
        end if;
      end if;
    exception
      when invalid_userenv_parm then
        null;
    END;
$body$
LANGUAGE PLPGSQL
