CREATE OR REPLACE FUNCTION logger_include_call_stack () RETURNS boolean AS $body$
DECLARE
 null or not $$no_op) $then
        result_cache relies_on(logger_prefs, logger_prefs_by_client_id)
    $end
  is
    l_call_stack_pref logger_prefs.pref_value%type;

BEGIN
    $if $$no_op $then
      return false;
    $else
      $if $$rac_lt_11_2 $then
