  /**
   * Returns date diff in "... sectons/minutes/days/etc ago" format
   *
   * Notes:
   *  - Private
   *
   * Related Tickets:
   *  -
   *
   * @author Tyler Muth
   * @created ???
   * @param p_date_start
   * @param p_date_stop
   * @return Text version of date diff
   */
CREATE OR REPLACE FUNCTION logger_date_text_format_base ( p_date_start timestamp(0), p_date_stop timestamp(0)) RETURNS varchar AS $body$
DECLARE

    x varchar(20);

BEGIN
    $if $$no_op $then
      return null;
    $else
      x :=
        case
          when p_date_stop-p_date_start < 1/1440
            then round(24*60*60*(p_date_stop-p_date_start)) || ' seconds'
          when p_date_stop-p_date_start < 1/24
            then round(24*60*(p_date_stop-p_date_start)) || ' minutes'
          when p_date_stop-p_date_start < 1
            then round(24*(p_date_stop-p_date_start)) || ' hours'
          when p_date_stop-p_date_start < 14
            then date_trunc('day', p_date_stop-p_date_start) || ' days'
          when p_date_stop-p_date_start < 60
            then trunc((p_date_stop-p_date_start)/7) || ' weeks'
          when p_date_stop-p_date_start < 365
            then round(months_between(p_date_stop,p_date_start)) || ' months'
          else round((months_between(p_date_stop,p_date_start)/12)::numeric,1) || ' years'
        end;
      x:= regexp_replace(x,'(^1 [[:alnum:]]{4,10})s','\1', 'g');
      x:= x || ' ago';
      return substr(x,1,20);
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION logger_date_text_format_base ( p_date_start timestamp(0), p_date_stop timestamp(0)) FROM PUBLIC;


  /**
   * Parses the callstack to get unit and line number
   *
   * Notes:
   *  - Private
   *
   * Related Tickets:
   *  -
   *
   * @author Tyler Muth
   * @created ???
   * @param p_callstack
   * @param o_unit
   * @param o_lineno
   */
CREATE OR REPLACE PROCEDURE logger_get_debug_info ( p_callstack text, o_unit INOUT text, o_lineno INOUT text ) AS $body$
DECLARE

    --
    l_callstack varchar(10000) := p_callstack;

BEGIN
    $if $$no_op $then
      null;
    $else
      l_callstack := substr( l_callstack, instr( l_callstack, chr(10), 1, 5 )+1 );
      l_callstack := substr( l_callstack, 1, instr( l_callstack, chr(10), 1, 1 )-1 );
      l_callstack := trim(both substr( l_callstack, position(' '  in l_callstack) ) );
      o_lineno := substr( l_callstack, 1, position(' '  in l_callstack)-1 );
      o_unit := trim(both substr( l_callstack, instr( l_callstack, ' ', -1, 1 ) ));
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_get_debug_info ( p_callstack text, o_unit INOUT text, o_lineno INOUT text ) FROM PUBLIC;


  /**
   * Main procedure that will store log data into logger_logs table
   *
   *
   * Modifications
   *  - 2.1.0: If text is > 4000 characters, it will be moved to the EXTRA column
   *
   * @author Tyler Muth
   * @created ???
   * @param p_text
   * @param p_log_level
   * @param p_scope
   * @param p_extra
   * @param p_callstack
   * @param p_params
   *
   */
CREATE OR REPLACE PROCEDURE logger_log_internal ( p_text text, p_log_level bigint, p_scope text, p_extra text default null, p_callstack text default null, p_params tab_param default logger.gc_empty_tab_param) AS $body$
DECLARE

    l_proc_name varchar(100);
    l_lineno varchar(100);
    l_text varchar(32767);
    l_callstack varchar(3000);
    l_extra logger_logs.extra%type;

BEGIN
    $if $$no_op $then
      null;
    $else
      l_text := p_text;

      -- Generate callstack text
      if (p_callstack IS NOT NULL AND p_callstack::text <> '') and logger_include_call_stack() then
        SELECT * FROM logger_get_debug_info(
          p_callstack => p_callstack, o_unit => l_proc_name, o_lineno => l_lineno) INTO STRICT l_proc_name, l_lineno;

        l_callstack  := regexp_replace(p_callstack,'^.*$','',1,4,'m', 'g');
        l_callstack  := regexp_replace(l_callstack,'^.*$','',1,1,'m', 'g');
        l_callstack  := ltrim(replace(l_callstack,chr(10)||chr(10),chr(10)),chr(10));

      end if;

      l_extra := logger_set_extra_with_params(p_extra => p_extra, p_params => p_params);

      current_setting('logger.g_log_id')::bigint := logger_ins_logger_logs(
        p_unit_name => upper(l_proc_name), p_scope => p_scope, p_logger_level =>p_log_level, p_extra => l_extra, p_text =>l_text, p_call_stack  =>l_callstack, p_line_no => l_lineno, po_id => current_setting('logger.g_log_id')::bigint);
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_log_internal ( p_text text, p_log_level bigint, p_scope text, p_extra text default null, p_callstack text default null, p_params tab_param default logger.gc_empty_tab_param) FROM PUBLIC;



