CREATE OR REPLACE FUNCTION logger_f_get_set_global_context ( p_ctx text ) RETURNS varchar AS $body$
DECLARE

      l_return varchar(255);

BEGIN
      $if $$logger_debug $then
        RAISE NOTICE 'Calling f_get_set_global_conext';
      $end

      l_return := upper(logger_get_pref(p_pref_name =>
        case
          when p_logger_log.logger_level = g_error then current_setting('logger.gc_ctx_plugin_fn_error')::varchar(30)
        end
      ));

      $if $$logger_debug $then
        RAISE NOTICE 'l_return: %', l_return;
      $end

      logger_save_global_context(p_attribute => p_ctx, p_value => l_return);
      return l_return;
    END;
