  /**
   * Converts string names to text value
   *
   * Changes
   *  - 2.1.0: Start to use global variables and correct numbers
   *
   * @author Tyler Muth
   * @created ???
   *
   * @param p_level String representation of level
   * @return level number. -1 if not found
   */
CREATE OR REPLACE FUNCTION logger_convert_level_char_to_num ( p_level text) RETURNS bigint AS $body$
DECLARE

    l_level         bigint;

BEGIN
    $if $$no_op $then
      return null;
    $else
      case p_level
        when g_off_name then l_level := g_off;
        when g_permanent_name then l_level := g_permanent;
        when g_error_name then l_level := g_error;
        when g_warning_name then l_level := g_warning;
        when g_information_name then l_level := g_information;
        when g_debug_name then l_level := g_debug;
        when g_timing_name then l_level := g_timing;
        when g_sys_context_name then l_level := g_sys_context;
        when g_apex_name then l_level := g_apex;
        else l_level := -1;
      end case;
    $end

    return l_level;
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION logger_convert_level_char_to_num ( p_level text) FROM PUBLIC;


  /**
   * Converts the logger level num to char format
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #48
   *
   * @author Martin D'Souza
   * @created 14-Jun-2014
   * @param p_level
   * @return Logger level string format
   */
CREATE OR REPLACE FUNCTION logger_convert_level_num_to_char ( p_level bigint) RETURNS varchar AS $body$
DECLARE

    l_return varchar(255);

BEGIN
    $if $$no_op $then
      null;
    $else
      l_return :=
        case p_level
          when g_off then g_off_name
          when g_permanent then g_permanent_name
          when g_error then g_error_name
          when g_warning then g_warning_name
          when g_information then g_information_name
          when g_debug then g_debug_name
          when g_timing then g_timing_name
          when g_sys_context then g_sys_context_name
          when g_apex then g_apex_name
          else null
        end;
    $end

    return l_return;
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION logger_convert_level_num_to_char ( p_level bigint) FROM PUBLIC;





  /**
   * Determines if the statement can be stored in LOGGER_LOGS
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #44: Expose publically
   *
   * @author Tyler Muth
   * @created ???
   *
   * @param p_level Level (number)
   * @return True of statement can be logged to LOGGER_LOGS
   */
CREATE OR REPLACE FUNCTION logger_ok_to_log (p_level bigint) RETURNS boolean AS $body$
DECLARE
 null or not $$no_op) $then
        result_cache relies_on(logger_prefs, logger_prefs_by_client_id)
    $end
  is
    l_level bigint;
    l_level_char varchar(50);

    $if $$logger_debug $then
      l_scope varchar(30) := 'ok_to_log';
    $END;
BEGIN
    $if $$no_op $then
      return false;
    $else

      $if $$logger_debug $then
        RAISE NOTICE '%: in function', l_scope;
      $end

      $if $$rac_lt_11_2 $then
        $if $$logger_debug $then
          RAISE NOTICE '%: calling get_level_number', l_scope;
        $end
        l_level := logger_get_level_number;
      $else
        l_level := sys_context(g_context_name,current_setting('logger.gc_ctx_attr_level')::varchar(5));

        if coalesce(l_level::text, '') = '' then
          $if $$logger_debug $then
            RAISE NOTICE '%: level was null, getting and setting in context', l_scope;
          $end

          l_level := logger_get_level_number;

          CALL logger_save_global_context(
            p_attribute => current_setting('logger.gc_ctx_attr_level')::varchar(5),
            p_value => l_level,
            p_client_id => sys_context('userenv','client_identifier'));
        end if;
      $end

      if l_level >= p_level then
        return true;
      else
        return false;
      end if;
   $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION logger_ok_to_log (p_level bigint) FROM PUBLIC;


