CREATE OR REPLACE FUNCTION logger_get_character_codes ( p_string text, p_show_common_codes boolean default true) RETURNS varchar AS $body$
DECLARE

    l_string  varchar(32767);
    l_dump    varchar(32767);
    l_return  varchar(32767);

BEGIN
    -- replace tabs with ^
    l_string := replace(p_string,chr(9),'^');
    -- replace all other control characters such as carriage return / line feeds with ~
    l_string := regexp_replace(l_string,'[[:cntrl:]]','~',1,0,'m', 'g');

    select dump(p_string) into STRICT l_dump;

    l_dump  := regexp_replace(l_dump,'(^.+?:)(.*)','\2',1,0, 'g'); -- get everything after the :
    l_dump  := ','||l_dump||','; -- leading and trailing commas
    l_dump  := replace(l_dump,',',',,'); -- double the commas. this is for the regex.
    l_dump  := regexp_replace(l_dump,'(,)([[:digit:]]{1})(,)','\1  \2\3',1,0, 'g'); -- lpad all single digit numbers out to 3
    l_dump  := regexp_replace(l_dump,'(,)([[:digit:]]{2})(,)','\1 \2\3',1,0, 'g');  -- lpad all double digit numbers out to 3
    l_dump  := ltrim(replace(l_dump,',,',','),','); -- remove the double commas
    l_dump  := lpad(' ',(5-position(',' in l_dump)),' ')||l_dump;

    -- replace every individual character with 2 spaces, itself and a comma so it lines up with the dump output
    l_string := ' '||regexp_replace(l_string,'(.){1}','  \1,',1,0, 'g');

    l_return := rtrim(l_dump,',') || chr(10) || rtrim(l_string,',');

    if p_show_common_codes then
      l_return := 'Common Codes: 13=Line Feed, 10=Carriage Return, 32=Space, 9=Tab'||chr(10) ||l_return;
    end if;

    return l_return;

  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION logger_get_character_codes ( p_string text, p_show_common_codes boolean default true) FROM PUBLIC;

  /**
   * Store APEX items in logger_logs_apex_items
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #115: Only log not-null values
   *  - #114: Bulk insert (no more row by row)
   *  - #54: Support for p_item_type
   *
   * @author Tyler Muth
   * @created ???
   * @param p_log_id logger_logs.id to reference
   * @param p_item_type Either the g_apex_item_type_... type or just the APEX page number for a specific page. It is assumed that it has been validated by the time it hits here.
   * @param p_log_null_items If set to false, null values won't be logged
   */
CREATE OR REPLACE PROCEDURE logger_snapshot_apex_items ( p_log_id logger_logs.id%type, p_item_type text, p_log_null_items boolean) AS $body$
DECLARE

    l_app_session bigint;
    l_app_id bigint;
    l_log_null_item_yn varchar(1);
    l_item_type varchar(30) := upper(p_item_type);
    l_item_type_page_id bigint;

BEGIN
    $if $$no_op $then
      null;
    $else
      $if $$apex $then
        l_app_session := v('APP_SESSION');
        l_app_id := v('APP_ID');

        l_log_null_item_yn := 'N';
        if p_log_null_items then
          l_log_null_item_yn := 'Y';
        end if;

        if logger_is_number(l_item_type) then
          l_item_type_page_id := (l_item_type)::numeric;
        end if;

        insert into logger_logs_apex_items(log_id,app_session,item_name,item_value)
        SELECT p_log_id, l_app_session, item_name, item_value
        from (
          -- Application items
          SELECT 1 app_page_seq, 0 page_id, item_name, v(item_name) item_value
          from apex_application_items
          where 1=1
            and application_id = l_app_id
            and l_item_type in (logger.g_apex_item_type_all, logger.g_apex_item_type_app)
          
union all

          -- Application page items
          select 2 app_page_seq, page_id, item_name, v(item_name) item_value
          from apex_application_page_items
          where 1=1
            and application_id = l_app_id
            and (
              1=2
              or l_item_type in (logger.g_apex_item_type_all, logger.g_apex_item_type_page)
              or ((l_item_type_page_id IS NOT NULL AND l_item_type_page_id::text <> '') and l_item_type_page_id = page_id)
            ) 
          ) alias8
        where 1=1
          and (l_log_null_item_yn = 'Y' or (item_value IS NOT NULL AND item_value::text <> '')) 
        order by app_page_seq, page_id, item_name;

      $end  -- $if $$apex $then
      null; -- Keep this in place incase APEX is not compiled
    $end  -- $$no_op
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_snapshot_apex_items ( p_log_id logger_logs.id%type, p_item_type text, p_log_null_items boolean) FROM PUBLIC;


  /**
   *
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #46: Added plugin support
   *
   * @author Tyler Muth
   * @created ???
   * @param p_text
   * @param p_scope
   * @param p_extra
   * @param p_params
   */
CREATE OR REPLACE PROCEDURE logger_log_error ( p_text text default null, p_scope text default null, p_extra text default null, p_params tab_param default logger.gc_empty_tab_param) AS $body$
DECLARE

    l_proc_name varchar(100);
    l_lineno varchar(100);
    l_text varchar(32767);
    l_call_stack varchar(4000);
    l_extra text;

BEGIN
    $if $$no_op $then
      null;
    $else
      if logger_ok_to_log(logger.g_error) then
        SELECT * FROM logger_get_debug_info(
          p_callstack => dbms_utility.format_call_stack, o_unit => l_proc_name, o_lineno => l_lineno) INTO STRICT l_proc_name, l_lineno;

        l_call_stack := dbms_utility.format_error_stack() || current_setting('logger.gc_line_feed')::varchar(1) || dbms_utility.format_error_backtrace;

        if (p_text IS NOT NULL AND p_text::text <> '') then
          l_text := p_text || current_setting('logger.gc_line_feed')::varchar(1) || current_setting('logger.gc_line_feed')::varchar(1);
        end if;

        l_text := l_text || dbms_utility.format_error_stack();

        l_extra := logger_set_extra_with_params(p_extra => p_extra, p_params => p_params);

        current_setting('logger.g_log_id')::bigint := logger_ins_logger_logs(
          p_unit_name => upper(l_proc_name), p_scope => p_scope, p_logger_level => logger.g_error, p_extra => l_extra, p_text => l_text, p_call_stack => l_call_stack, p_line_no => l_lineno, po_id => current_setting('logger.g_log_id')::bigint);

        -- Plugin
        $if $$logger_plugin_error $then

          if not current_setting('logger.g_in_plugin_error')::boolean then
            current_setting('logger.g_plug_logger_log_error')::rec_logger_log.logger_level := logger.g_error;
            current_setting('logger.g_plug_logger_log_error')::rec_logger_log.id := current_setting('logger.g_log_id')::bigint;

            $if $$logger_debug $then
              RAISE NOTICE 'Starting call to run_plugin error';
            $end

            run_plugin(p_logger_log => current_setting('logger.g_plug_logger_log_error')::rec_logger_log);
          end if; -- not g_in_plugin_error
        $end

      end if; -- ok_to_log
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_log_error ( p_text text default null, p_scope text default null, p_extra text default null, p_params tab_param default logger.gc_empty_tab_param) FROM PUBLIC;


