--
-- dblink wrapper to call function logger_log_apex_items as an autonomous transaction
--
CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE logger_log_apex_items ( p_text text default 'Log APEX Items', p_scope logger_logs.scope%type default null, p_item_type text default logger.g_apex_item_type_all, p_log_null_items boolean default true, p_level logger_logs.logger_level%type default null) AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL logger_log_apex_items_atx ( ' || quote_nullable(p_text) || ',' || quote_nullable(p_scope) || ',' || quote_nullable(p_item_type) || ',' || quote_nullable(p_log_null_items) || ',' || quote_nullable(p_level) || ' )';
	PERFORM * FROM dblink(v_conn_str, v_query) AS p (ret boolean);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;



  /**
   * Log's APEX items
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #115 Only log not-null values
   *  - #29 Support for definging level
   *  - #54: Add p_item_type
   *
   * @author Tyler Muth
   * @created ???
   * @param p_text
   * @param p_scope
   * @param p_item_type Either the g_apex_item_type_... type or just the APEX page number for a specific page.
   * @param p_log_null_items If set to false, null values won't be logged
   * @param p_level Highest level to run at (default logger.g_debug). Example. If you set to logger.g_error it will work when both in DEBUG and ERROR modes. However if set to logger.g_debug(default) will not store values when level is set to ERROR.
   */
CREATE OR REPLACE PROCEDURE logger_log_apex_items_atx ( p_text text default 'Log APEX Items', p_scope logger_logs.scope%type default null, p_item_type text default logger.g_apex_item_type_all, p_log_null_items boolean default true, p_level logger_logs.logger_level%type default null) AS $body$
DECLARE

    l_error varchar(4000);
BEGIN
    $if $$no_op $then
      null;
    $else
      if logger_ok_to_log(coalesce(p_level, logger.g_debug)) then

        $if $$apex $then
          -- Validate p_item_type
          CALL logger_assert(
            p_condition => upper(p_item_type) in (logger.g_apex_item_type_all, logger.g_apex_item_type_app, logger.g_apex_item_type_page) or logger_is_number(p_item_type),
            p_message => logger_sprintf('APEX Item Scope was set to %s. Must be %s, %s, %s, or page number', p_item_type, logger.g_apex_item_type_all, logger.g_apex_item_type_page, logger.g_apex_item_type_page));

          CALL logger_log_internal(
            p_text => p_text,
            p_log_level => coalesce(p_level, logger.g_apex),
            p_scope => p_scope);

          CALL logger_snapshot_apex_items(
            p_log_id => current_setting('logger.g_log_id')::bigint,
            p_item_type => upper(p_item_type),
            p_log_null_items => p_log_null_items);
        $else
          l_error := 'Error! Logger is not configured for APEX yet. ';

          CALL logger_log_internal(
            p_text => l_error,
            p_log_level => logger.g_apex,
            p_scope => p_scope);
        $end
      end if;
    $END;
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_log_apex_items ( p_text text default 'Log APEX Items', p_scope logger_logs.scope%type default null, p_item_type text default logger.g_apex_item_type_all, p_log_null_items boolean default true, p_level logger_logs.logger_level%type default null) FROM PUBLIC; -- REVOKE ALL ON PROCEDURE logger_log_apex_items_atx ( p_text text default 'Log APEX Items', p_scope logger_logs.scope%type default null, p_item_type text default logger.g_apex_item_type_all, p_log_null_items boolean default true, p_level logger_logs.logger_level%type default null) FROM PUBLIC;


  /**
   *
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #73/#75: Use localtimestamp
   *
   * @author Tyler Muth
   * @created ???
   * @param p_unit
   * @param p_log_in_table
   */
CREATE OR REPLACE PROCEDURE logger_time_start ( p_unit text, p_log_in_table boolean default true) AS $body$
DECLARE

    l_proc_name varchar(100);
    l_text varchar(4000);
    l_pad varchar(100);

BEGIN
    $if $$no_op $then
      null;
    $else
      if logger_ok_to_log(logger.g_debug) then
        PERFORM set_config('logger.g_running_timers', current_setting('logger.g_running_timers')::integer + 1, false);

        if current_setting('logger.g_running_timers')::integer > 1 then
          -- Use 'a' since lpad requires a value to pad
          l_pad := replace(lpad('a',current_setting('logger.g_running_timers')::integer,'>')||' ', 'a', null);
        end if;

        current_setting('logger.g_proc_start_times')::ts_array(p_unit) := localtimestamp;

        l_text := l_pad||'START: '||p_unit;

        if p_log_in_table then
           := logger_ins_logger_logs(
            p_unit_name => p_unit, p_logger_level => g_timing, p_text =>l_text, po_id => current_setting('logger.g_log_id')::bigint);
        end if;
      end if;
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_time_start ( p_unit text, p_log_in_table boolean default true) FROM PUBLIC;

  /**
   *
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #73: Remove additional timer decrement since it was already happening in function time_stop
   *
   * @author Tyler Muth
   * @created ???
   * @param p_scope
   * @param p_unit
   */
CREATE OR REPLACE PROCEDURE logger_time_stop ( p_unit text, p_scope text default null) AS $body$
DECLARE

    l_time_string varchar(50);
    l_text varchar(4000);
    l_pad varchar(100);

BEGIN
    $if $$no_op $then
      null;
    $else
      if logger_ok_to_log(logger.g_debug) then
        if current_setting('logger.g_proc_start_times')::ts_array.exists(p_unit) then

          if current_setting('logger.g_running_timers')::integer > 1 then
            -- Use 'a' since lpad requires a value to pad
            l_pad := replace(lpad('a',current_setting('logger.g_running_timers')::integer,'>')||' ', 'a', null);
          end if;

          --l_time_string := rtrim(regexp_replace(systimestamp-(g_proc_start_times(p_unit)),'.+?[[:space:]](.*)','\1',1,0),0);
          -- Function time_stop will decrement the timers and pop the name from the g_proc_start_times array
          l_time_string := logger_time_stop(
            p_unit => p_unit,
            p_log_in_table => false);

          l_text := l_pad||'STOP : '||p_unit ||' - '||l_time_string;

           := logger_ins_logger_logs(
            p_unit_name => p_unit, p_scope => p_scope, p_logger_level => g_timing, p_text =>l_text, po_id => current_setting('logger.g_log_id')::bigint);
        end if;
      end if;
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_time_stop ( p_unit text, p_scope text default null) FROM PUBLIC;


  /**
   *
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #73/#75: Trim timezone from systimestamp to localtimestamp
   *
   * @author Tyler Muth
   * @created ???
   * @param p_unit
   * @param p_scope
   * @param p_log_in_table
   * @return Timer string
   */
CREATE OR REPLACE FUNCTION logger_time_stop ( p_unit text, p_scope text default null, p_log_in_table boolean default true) RETURNS varchar AS $body$
DECLARE

    l_time_string varchar(50);

BEGIN
    $if $$no_op $then
      null;
    $else
      if logger_ok_to_log(logger.g_debug) then
        if current_setting('logger.g_proc_start_times')::ts_array.exists(p_unit) then

          l_time_string := rtrim(regexp_replace(localtimestamp - (current_setting('logger.g_proc_start_times')::ts_array(p_unit)),'.+?[[:space:]](.*)','\1',1,0),0);

          current_setting('logger.g_proc_start_times')::ts_array.delete(p_unit);
          PERFORM set_config('logger.g_running_timers', current_setting('logger.g_running_timers')::integer - 1, false);

          if p_log_in_table then
             := logger_ins_logger_logs(
              p_unit_name => p_unit, p_scope => p_scope, p_logger_level => g_timing, p_text => l_time_string, po_id => current_setting('logger.g_log_id')::bigint);
          end if;

          return l_time_string;

        end if;
      end if;
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION logger_time_stop ( p_unit text, p_scope text default null, p_log_in_table boolean default true) FROM PUBLIC;


  /**
   *
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #73/#75: Trim timezone from systimestamp to localtimestamp
   *
   * @author Tyler Muth
   * @created ???
   * @param p_unit
   * @param p_scope
   * @param p_log_in_table
   * @return Timer in seconds
   */
CREATE OR REPLACE FUNCTION logger_time_stop_seconds ( p_unit text, p_scope text default null, p_log_in_table boolean default true) RETURNS bigint AS $body$
DECLARE

    l_time_string varchar(50);
    l_seconds bigint;
    l_interval interval day to second;


BEGIN
    $if $$no_op $then
      null;
    $else
      if logger_ok_to_log(logger.g_debug) then
        if current_setting('logger.g_proc_start_times')::ts_array.exists(p_unit) then
          l_interval := localtimestamp - (current_setting('logger.g_proc_start_times')::ts_array(p_unit));
          l_seconds := extract(day from l_interval) * 86400 + extract(hour from l_interval) * 3600 + extract(minute from l_interval) * 60 + extract(second from l_interval);

          current_setting('logger.g_proc_start_times')::ts_array.delete(p_unit);
          PERFORM set_config('logger.g_running_timers', current_setting('logger.g_running_timers')::integer - 1, false);

          if p_log_in_table then
             := logger_ins_logger_logs(
              p_unit_name => p_unit, p_scope => p_scope, p_logger_level => g_timing, p_text => l_seconds, po_id => current_setting('logger.g_log_id')::bigint);
          end if;

          return l_seconds;

        end if;
      end if;
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION logger_time_stop_seconds ( p_unit text, p_scope text default null, p_log_in_table boolean default true) FROM PUBLIC;


  /**
   * Resets all timers
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  -
   *
   * @author Tyler Muth
   * @created ???
   */
CREATE OR REPLACE PROCEDURE logger_time_reset () AS $body$
BEGIN
    $if $$no_op $then
      null;
    $else
      if logger_ok_to_log(logger.g_debug) then
        PERFORM set_config('logger.g_running_timers', 0, false);
        current_setting('logger.g_proc_start_times')::ts_array.delete;
      end if;
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_time_reset () FROM PUBLIC;

  /**
   * Returns Global or User preference
   * User preference is only valid for LEVEL and INCLUDE_CALL_STACK
   *  - If a user setting exists, it will be returned, if not the system level preference will be return
   *
   * Updates
   *  - 2.0.0: Added user preference support
   *  - 2.1.2: Fixed issue when calling set_level with the same client_id multiple times
   *
   * Related Tickets:
   *  - #127: Added logger_prefs.pref_type
   *
   * @author Tyler Muth
   * @created ???
   *
   * @param p_pref_name
   * @param p_pref_type Namespace for preference
   */
CREATE OR REPLACE FUNCTION logger_get_pref ( p_pref_name logger_prefs.pref_name%type, p_pref_type logger_prefs.pref_type%type default logger.g_pref_type_logger) RETURNS varchar AS $body$
DECLARE
 null or not $$no_op $then
        relies_on(logger_prefs, logger_prefs_by_client_id)
      $end
    $end
  is
    l_scope varchar(30) := 'get_pref';
    l_pref_value logger_prefs.pref_value%type;
    l_client_id logger_prefs_by_client_id.client_id%type;
    l_pref_name logger_prefs.pref_name%type := upper(p_pref_name);
    l_pref_type logger_prefs.pref_type%type := upper(p_pref_type);

BEGIN

    $if $$no_op $then
      return null;
    $else
      $if $$logger_debug $then
        RAISE NOTICE '% select pref', l_scope;
      $end

      l_client_id := sys_context('userenv','client_identifier');

      select pref_value
      into STRICT l_pref_value
      from (
        SELECT pref_value, row_number() over (order by rank) rn
        from (
          -- Client specific logger levels trump system level logger level
          SELECT
            case
              when l_pref_name = current_setting('logger.gc_pref_level')::logger_prefs.pref_name%type then logger_level
              when l_pref_name = current_setting('logger.gc_pref_include_call_stack')::logger_prefs.pref_name%type then include_call_stack
            end pref_value,
            1 rank
          from logger_prefs_by_client_id
          where 1=1
            and client_id = l_client_id
            -- Only try to get prefs at a client level if pref is in LEVEL or INCLUDE_CALL_STACK
            and (l_client_id IS NOT NULL AND l_client_id::text <> '')
            -- #127
            -- Prefs by client aren't available for custom prefs right now
            -- Only need to search this table if p_pref_type is LOGGER
            and l_pref_type = logger.g_pref_type_logger
            and l_pref_name in (current_setting('logger.gc_pref_level')::logger_prefs.pref_name%type, current_setting('logger.gc_pref_include_call_stack')::logger_prefs.pref_name%type)
          
union

          -- System level configuration
          select pref_value, 2 rank
          from logger_prefs
          where 1=1
            and pref_name = l_pref_name
            and pref_type = l_pref_type
        ) alias8 
      ) alias9 
      where rn = 1;
      return l_pref_value;
    $end

  exception
    when no_data_found then
      return null;
    when others then
      raise;
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION logger_get_pref ( p_pref_name logger_prefs.pref_name%type, p_pref_type logger_prefs.pref_type%type default logger.g_pref_type_logger) FROM PUBLIC;


  /**
   * Sets a preference
   * If it does not exist, it will insert one
   *
   * Notes:
   *  - Does not support setting system preferences
   *
   * Related Tickets:
   *  - #127
   *
   * @author Alex Nuijten / Martin D'Souza
   * @created 24-APR-2015
   * @param p_pref_type
   * @param p_pref_name
   * @param p_pref_value
   */
CREATE OR REPLACE PROCEDURE logger_set_pref ( p_pref_type logger_prefs.pref_type%type, p_pref_name logger_prefs.pref_name%type, p_pref_value logger_prefs.pref_value%type) AS $body$
DECLARE

    l_pref_type logger_prefs.pref_type%type := trim(both upper(p_pref_type));
    l_pref_name logger_prefs.pref_name%type := trim(both upper(p_pref_name));

BEGIN

    $if $$no_op $then
      null;
    $else
      if l_pref_type = logger.g_pref_type_logger then
        RAISE EXCEPTION '%', 'Can not set ' || l_pref_type || '. Reserved for Logger' USING ERRCODE = '45001';
      end if;

      merge into logger_prefs p
      using(SELECT l_pref_type pref_type, l_pref_name pref_name, p_pref_value pref_value
             ) args
      on ( 1=1
        and p.pref_type = args.pref_type
        and p.pref_name = args.pref_name)
      when matched then
        update
        set p.pref_value =  args.pref_value
      when not matched then
        insert(pref_type, pref_name ,pref_value)
      values (args.pref_type, args.pref_name ,args.pref_value);
    $end  -- $no_op
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_set_pref ( p_pref_type logger_prefs.pref_type%type, p_pref_name logger_prefs.pref_name%type, p_pref_value logger_prefs.pref_value%type) FROM PUBLIC;

  /**
   * Removes a Preference
   *
   * Notes:
   *  - Does not support setting system preferences
   *
   * Related Tickets:
   *  - #127
   *
   * @author Alex Nuijten / Martin D'Souza
   * @created 30-APR-2015
   *
   * @param p_pref_type
   * @param p_pref_name
   */
CREATE OR REPLACE PROCEDURE logger_del_pref ( p_pref_type logger_prefs.pref_type%type, p_pref_name logger_prefs.pref_name%type) AS $body$
DECLARE

    l_pref_type logger_prefs.pref_type%type := trim(both upper(p_pref_type));
    l_pref_name logger_prefs.pref_name%type := trim(both upper(p_pref_name));

BEGIN
    $if $$no_op $then
      null;
    $else
      if l_pref_type = logger.g_pref_type_logger then
        RAISE EXCEPTION '%', 'Can not delete ' || l_pref_type || '. Reserved for Logger' USING ERRCODE = '45001';
      end if;

      delete from logger_prefs
      where 1=1
        and pref_type = l_pref_type
        and pref_name = l_pref_name;
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_del_pref ( p_pref_type logger_prefs.pref_type%type, p_pref_name logger_prefs.pref_name%type) FROM PUBLIC;

--
-- dblink wrapper to call function logger_purge as an autonomous transaction
--
CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE logger_purge ( p_purge_after_days bigint default null, p_purge_min_level bigint DEFAULT NULL) AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL logger_purge_atx ( ' || quote_nullable(p_purge_after_days) || ',' || quote_nullable(p_purge_min_level) || ' )';
	PERFORM * FROM dblink(v_conn_str, v_query) AS p (ret boolean);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;



  /**
   * Purges logger_logs data
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  - #48 Support for overloading
   *
   * @author Martin D'Souza
   * @created 14-Jun-2014
   * @param p_purge_after_days
   * @param p_purge_min_level
   */
CREATE OR REPLACE PROCEDURE logger_purge_atx ( p_purge_after_days bigint default null, p_purge_min_level bigint DEFAULT NULL) AS $body$
DECLARE

    $if $$coalesce(no_op::text, '') = '' or not $$no_op $then
      l_purge_after_days bigint := coalesce(p_purge_after_days,logger_get_pref(logger.gc_pref_purge_after_days));
    $end;
BEGIN
    $if $$no_op $then
      null;
    $else

      if admin_security_check then
        delete
          from logger_logs
         where logger_level >= p_purge_min_level
           and time_stamp < statement_timestamp() - (l_purge_after_days * ('1'||'day')::interval)
           and logger_level > g_permanent;
      end if;
    $END;
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_purge ( p_purge_after_days bigint default null, p_purge_min_level bigint DEFAULT NULL) FROM PUBLIC; -- REVOKE ALL ON PROCEDURE logger_purge_atx ( p_purge_after_days bigint default null, p_purge_min_level bigint DEFAULT NULL) FROM PUBLIC;


  /**
   * Wrapper for logger_purge(to accept number for purge_min_level)
   *
   * Notes:
   *  -
   *
   * Related Tickets:
   *  -
   *
   * @author Tyler Muth
   * @created ???
   * @param p_purge_after_days
   * @param p_purge_min_level
   */
CREATE OR REPLACE PROCEDURE logger_purge ( p_purge_after_days text default null, p_purge_min_level text default null) AS $body$
BEGIN
    $if $$no_op $then
      null;
    $else
      CALL logger_purge(
        p_purge_after_days => (p_purge_after_days)::numeric ,
        p_purge_min_level => logger_convert_level_char_to_num(coalesce(p_purge_min_level,logger_get_pref(current_setting('logger.gc_pref_purge_min_level')::logger_prefs.pref_name%type))));
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_purge ( p_purge_after_days text default null, p_purge_min_level text default null) FROM PUBLIC;

