CREATE OR REPLACE PROCEDURE logger_display_output ( p_name text, p_value text) AS $body$
BEGIN
      if l_output_format = 'SQL-DEVELOPER' then
        RAISE NOTICE '<pre>%: <strong>%</strong></pre>', rpad(p_name,25), p_value;
      elsif l_output_format = 'HTTP' then
        htp.p('<br />'||p_name||': <strong>'||p_value||'</strong>');
      else
        RAISE NOTICE '%: %', rpad(p_name,25), p_value;
      end if;
    END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_display_output ( p_name text, p_value text) FROM PUBLIC;

