CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE logger_unset_client_level (p_client_id text) AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL logger_unset_client_level_atx ( ' || quote_nullable(p_client_id) || ' )';
	PERFORM * FROM dblink(v_conn_str, v_query) AS p (ret boolean);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;



  /**
   * Unsets a logger level for a given client_id
   * This will only unset for client specific logger levels
   * Note: An explicit commit will occur in this procedure
   *
   * @author Martin D'Souza
   * @created 6-Apr-2013
   *
   * @param p_client_id Client identifier (case sensitive) to unset logger level in.
   */
CREATE OR REPLACE PROCEDURE logger_unset_client_level_atx (p_client_id text) AS $body$
BEGIN
    $if $$no_op $then
      null;
    $else
      CALL logger_assert((p_client_id IS NOT NULL AND p_client_id::text <> ''), 'p_client_id is a required value');

      -- Remove from client specific table
      delete from logger_prefs_by_client_id
      where client_id = p_client_id;

      -- Remove context values
      dbms_session.clear_context(
       namespace => g_context_name,
       client_id => p_client_id,
       attribute => current_setting('logger.gc_ctx_attr_level')::varchar(5));

      dbms_session.clear_context(
       namespace => g_context_name,
       client_id => p_client_id,
       attribute => current_setting('logger.gc_ctx_attr_include_call_stack')::varchar(18));

    $END;
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_unset_client_level (p_client_id text) FROM PUBLIC; -- REVOKE ALL ON PROCEDURE logger_unset_client_level_atx (p_client_id text) FROM PUBLIC;


  /**
   * Unsets client_level that are stale (i.e. past thier expiry date)
   *
   * @author Martin D'Souza
   * @created 7-Apr-2013
   *
   * @param p_unset_after_hours If null then preference UNSET_CLIENT_ID_LEVEL_AFTER_HOURS
   */
CREATE OR REPLACE PROCEDURE logger_unset_client_level () AS $body$
DECLARE


  x RECORD;

BEGIN
    $if $$no_op $then
      null;
    $else
      for x in (
        SELECT client_id
        from logger_prefs_by_client_id
        where clock_timestamp() > expiry_date ) loop

        CALL logger_unset_client_level(p_client_id => x.client_id);
      end loop;
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_unset_client_level () FROM PUBLIC;


  /**
   * Unsets all client specific preferences
   * An implicit commit will occur as unset_client_level makes a commit
   *
   * @author Martin D'Souza
   * @created 7-Apr-2013
   *
   */
CREATE OR REPLACE PROCEDURE logger_unset_client_level_all () AS $body$
DECLARE


  x RECORD;

BEGIN
    $if $$no_op $then
      null;
    $else
      for x in (SELECT client_id from logger_prefs_by_client_id) loop
        CALL logger_unset_client_level(p_client_id => x.client_id);
      end loop;
    $end
  END;
$body$
LANGUAGE PLPGSQL
;
