   * @param p_params Table of parameters (param will be appended to this)
   * @param p_name Name
   * @param p_val Value in its format. Will be converted to string
   */
CREATE OR REPLACE PROCEDURE logger_append_param ( p_params INOUT logger.tab_param, p_name text, p_val text ) AS $body$
