--
-- dblink wrapper to call function logger_ins_logger_logs as an autonomous transaction
--
CREATE EXTENSION IF NOT EXISTS dblink;

CREATE OR REPLACE PROCEDURE logger_ins_logger_logs ( p_logger_level logger_logs.logger_level%type, p_text text default null, -- Not using type since want to be able to pass in 32767 characters
 p_scope logger_logs.scope%type default null, p_call_stack logger_logs.call_stack%type default null, p_unit_name logger_logs.unit_name%type default null, p_line_no logger_logs.line_no%type default null, p_extra logger_logs.extra%type default null, po_id INOUT logger_logs.id%type  DEFAULT NULL) AS $body$
DECLARE
	-- Change this to reflect the dblink connection string
	v_conn_str  text := format('port=%s dbname=%s user=%s', current_setting('port'), current_database(), current_user);
	v_query     text;

BEGIN
	v_query := 'CALL logger_ins_logger_logs_atx ( ' || quote_nullable(p_logger_level) || ',' || quote_nullable(p_text) || ',' || quote_nullable(
) || ',' || quote_nullable(p_call_stack) || ',' || quote_nullable(p_unit_name) || ',' || quote_nullable(p_line_no) || ',' || quote_nullable(p_extra) || ',' || quote_nullable(po_id) || ' )';
	SELECT v_ret INTO po_id FROM dblink(v_conn_str, v_query) AS p (v_ret NULL);

END;
$body$ LANGUAGE plpgsql SECURITY DEFINER;



  /**
   * Handles inserts into LOGGER_LOGS.
   *
   * Replaces trigger for both performance issues and to be a single location for all insert statements
   *
   * autonomous_transaction so commit will be performed after insert
   *
   * @author Martin D'Souza
   * @created 30-Jul-2013
   *
   * Related Issues
   *  - #31: Initial ticket
   *  - #51: Added SID column
   *  - #70: Fixed missing no_op flag
   *  - #109: Fix length check for multibyte characters
   *
   * @param p_logger_level
   * @param p_text
   * @param p_scope
   * @param p_call_stack
   * @param p_unit_name
   * @param p_line_no
   * @param p_extra
   * @param po_id ID entered into logger_logs for this record
   */
CREATE OR REPLACE PROCEDURE logger_ins_logger_logs_atx ( p_logger_level logger_logs.logger_level%type, p_text text default null,
 p_scope logger_logs.scope%type default null, p_call_stack logger_logs.call_stack%type default null, p_unit_name logger_logs.unit_name%type default null, p_line_no logger_logs.line_no%type default null, p_extra logger_logs.extra%type default null, po_id INOUT logger_logs.id%type  DEFAULT NULL) AS $body$
DECLARE
l_id logger_logs.id%type;
    l_text varchar(32767) := p_text;
    l_extra logger_logs.extra%type := p_extra;
    l_tmp_clob text;


BEGIN
    $if $$no_op $then
      null;
    $else
      -- Using select into to support version older than 11gR1 (see Issue 26)
      select nextval('logger_logs_seq')
      into STRICT po_id
;

      -- 2.1.0: If text is > 4000 characters, it will be moved to the EXTRA column (Issue 17)
      $if $$large_text_column $then  -- Only check for moving to Clob if small text column
        -- Don't do anything since column supports large text
      $else
        if lengthb(l_text) > 4000 then  -- #109 Using lengthb for multibyte characters
          if coalesce(l_extra::text, '') = '' then
            l_extra := l_text;
          else
            -- Using temp clob for performance purposes: http://www.talkapex.com/2009/06/how-to-quickly-append-varchar2-to-clob.html
            l_tmp_clob := current_setting('logger.gc_line_feed')::varchar(1) || current_setting('logger.gc_line_feed')::varchar(1) || '*** Content moved from TEXT column ***' || current_setting('logger.gc_line_feed')::varchar(1);
            l_extra := l_extra || l_tmp_clob;
            l_tmp_clob := l_text;
            l_extra := l_extra || l_text;
          end if; -- l_extra is not null
          l_text := 'Text moved to EXTRA column';
        end if; -- length(l_text)
      $end

      insert into logger_logs(
        id, logger_level, text,
        time_stamp, scope, module,
        action,
        user_name,
        client_identifier,
        call_stack, unit_name, line_no ,
        scn,
        extra,
        sid,
        client_info
        )
       values (
         po_id, p_logger_level, l_text,
         statement_timestamp(), lower(p_scope), sys_context('userenv','module'),
         sys_context('userenv','action'),
         coalesce($if $$apex $then apex_application.g_user $else user $end,user),
         sys_context('userenv','client_identifier'),
         p_call_stack, upper(p_unit_name), p_line_no,
         null,
         l_extra,
         (sys_context('userenv','sid'))::numeric ,
         sys_context('userenv','client_info')
         );

    $end  -- $$NO_OP
    commit;
  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON PROCEDURE logger_ins_logger_logs ( p_logger_level logger_logs.logger_level%type, p_text text default null, p_scope logger_logs.scope%type default null, p_call_stack logger_logs.call_stack%type default null, p_unit_name logger_logs.unit_name%type default null, p_line_no logger_logs.line_no%type default null, p_extra logger_logs.extra%type default null, po_id INOUT logger_logs.id%type  DEFAULT NULL) FROM PUBLIC; -- REVOKE ALL ON PROCEDURE logger_ins_logger_logs_atx ( p_logger_level logger_logs.logger_level%type, p_text text default null, p_scope logger_logs.scope%type default null, p_call_stack logger_logs.call_stack%type default null, p_unit_name logger_logs.unit_name%type default null, p_line_no logger_logs.line_no%type default null, p_extra logger_logs.extra%type default null, po_id INOUT logger_logs.id%type  DEFAULT NULL) FROM PUBLIC;


  /**
   * Does string replacement similar to C's sprintf
   *
   * Notes:
   *  - Uses the following replacement algorithm (in following order)
   *    - Replaces %s<n> with p_s<n>
   *    - Occurrences of %s (no number) are replaced with p_s1..p_s10 in order that they appear in text
   *    - %% is escaped to %
   *  - As this function could be useful for non-logging purposes will not apply a NO_OP to it for conditional compilation
   *
   * Related Tickets:
   *  - #32: Also see #59
   *  - #95: Remove no_op clause
   *
   * @author Martin D'Souza
   * @created 15-Jun-2014
   * @param p_str Messsage to format using %s and %d replacement strings
   * @param p_s1
   * @param p_s2
   * @param p_s3
   * @param p_s4
   * @param p_s5
   * @param p_s6
   * @param p_s7
   * @param p_s8
   * @param p_s9
   * @param p_s10
   * @return p_msg with strings replaced
   */
CREATE OR REPLACE FUNCTION logger_sprintf ( p_str text, p_s1 text default null, p_s2 text default null, p_s3 text default null, p_s4 text default null, p_s5 text default null, p_s6 text default null, p_s7 text default null, p_s8 text default null, p_s9 text default null, p_s10 text default null) RETURNS varchar AS $body$
DECLARE

    l_return varchar(4000);
    c_substring_regexp constant varchar(10) := '%s';


BEGIN
    l_return := p_str;

    -- Replace %s<n> with p_s<n>``
    for i in 1..10 loop
      l_return := regexp_replace(l_return, c_substring_regexp || i,
        case
          when i = 1 then p_s1
          when i = 2 then p_s2
          when i = 3 then p_s3
          when i = 4 then p_s4
          when i = 5 then p_s5
          when i = 6 then p_s6
          when i = 7 then p_s7
          when i = 8 then p_s8
          when i = 9 then p_s9
          when i = 10 then p_s10
          else null
        end,
        1,0,'c', 'g');
    end loop;

    $if $$logger_debug $then
      RAISE NOTICE 'Before utl_lms: %', l_return;
    $end

    -- Replace any occurences of %s with p_s<n> (in order) and escape %% to %
    l_return := utl_lms.format_message(l_return,p_s1, p_s2, p_s3, p_s4, p_s5, p_s6, p_s7, p_s8, p_s9, p_s10);

    return l_return;

  END;
$body$
LANGUAGE PLPGSQL
;
-- REVOKE ALL ON FUNCTION logger_sprintf ( p_str text, p_s1 text default null, p_s2 text default null, p_s3 text default null, p_s4 text default null, p_s5 text default null, p_s6 text default null, p_s7 text default null, p_s8 text default null, p_s9 text default null, p_s10 text default null) FROM PUBLIC;


  /**
   * Returns the rec_logger_logs for given logger_level
   * Used for plugin.
   * Not meant to be called by general public, and thus not documented
   *
   * Notes:
   *  - -- FUTURE mdsouza: Add tests for this (#86)
   *
   * Related Tickets:
   *  - #46
   *
   * @author Martin D'Souza
   * @created 11-Mar-2015
   * @param p_logger_level Logger level of plugin wanted to return
   * @return Logger rec based on plugin type
   */
CREATE OR REPLACE FUNCTION logger_get_plugin_rec ( p_logger_level logger_logs.logger_level%type) RETURNS LOGGER.REC_LOGGER_LOG AS $body$
BEGIN

    if p_logger_level = logger.g_error then
      return current_setting('logger.g_plug_logger_log_error')::rec_logger_log;
    end if;
  END;
$body$
LANGUAGE PLPGSQL
;
